    const per = (n) => TGT[F[n][0]].h / (F[n][2] - F[n][1]);
    const d0 = Math.abs((holder.dExact ?? Infinity) - dist) < 13 ? holder.dExact : dist;
    holder.scene = [sk, j]; holder.sceneTgt = F[j][0]; holder.dExact = d0 * per(j) / per(i);
